import { useState, useEffect, useCallback } from 'react'

const KEY = 'cloakcash_txs'

function load() {
  try { return JSON.parse(localStorage.getItem(KEY) || '[]') } catch { return [] }
}
function save(txs) {
  localStorage.setItem(KEY, JSON.stringify(txs.slice(0, 100)))
}

// Global singleton state — all hook instances share the same array
let _txs = load()
const _listeners = new Set()

function notify(next) {
  _txs = next
  save(next)
  _listeners.forEach(fn => fn(next))
}

export function useTxHistory() {
  const [txs, setTxs] = useState(() => _txs)

  useEffect(() => {
    _listeners.add(setTxs)
    // sync if another tab wrote to localStorage
    function onStorage(e) {
      if (e.key === KEY) { const v = load(); notify(v) }
    }
    window.addEventListener('storage', onStorage)
    return () => { _listeners.delete(setTxs); window.removeEventListener('storage', onStorage) }
  }, [])

  const addTx = useCallback((tx) => {
    notify([{ ...tx, ts: Date.now() }, ..._txs.filter(t => t.hash !== tx.hash)])
  }, [])

  const updateTx = useCallback((hash, patch) => {
    notify(_txs.map(t => t.hash === hash ? { ...t, ...patch } : t))
  }, [])

  const deleteTx = useCallback((hash) => {
    notify(_txs.filter(t => t.hash !== hash))
  }, [])

  const clearTxs = useCallback(() => {
    notify([])
    localStorage.removeItem(KEY)
  }, [])

  return { txs, addTx, updateTx, deleteTx, clearTxs }
}
